//! COM plumbing: the class factory and the `IObjectWithSite` object that XAML Diagnostics
//! creates after `InitializeXamlDiagnosticsEx` loads this DLL into Explorer.
// Both lints fire inside the code generated by windows-core's `#[implement]`.
#![allow(clippy::ref_as_ptr, clippy::inline_always)]

use crate::bindings::{
    CLASS_E_NOAGGREGATION, E_INVALIDARG, E_NOTIMPL, E_UNEXPECTED, IClassFactory,
    IClassFactory_Impl, IObjectWithSite, IObjectWithSite_Impl,
};
use crate::guard::guard;
use crate::tree;
use crate::xamlom::{IVisualTreeService2, IXamlDiagnostics};
use hyaline_core::tap::InitData;
use std::ffi::c_void;
use windows_core::{BOOL, BSTR, Error, GUID, IUnknown, Interface, Ref, Result, implement};

#[implement(IClassFactory)]
pub struct Factory;

impl IClassFactory_Impl for Factory_Impl {
    fn CreateInstance(
        &self,
        outer: Ref<IUnknown>,
        iid: *const GUID,
        out: *mut *mut c_void,
    ) -> Result<()> {
        guard(Err(E_UNEXPECTED.into()), || {
            if outer.is_some() {
                return Err(CLASS_E_NOAGGREGATION.into());
            }
            let site: IObjectWithSite = Site.into();
            // SAFETY: `iid` and `out` come from COM and are valid for this call.
            unsafe { site.query(iid, out) }.ok()
        })
    }

    fn LockServer(&self, _lock: BOOL) -> Result<()> {
        Ok(())
    }
}

#[implement(IObjectWithSite)]
struct Site;

impl IObjectWithSite_Impl for Site_Impl {
    fn SetSite(&self, site: Ref<IUnknown>) -> Result<()> {
        guard(Err(E_UNEXPECTED.into()), || {
            // XAML Diagnostics passes null when it disconnects; nothing to do then.
            let Some(site) = site.as_ref() else {
                return Ok(());
            };
            let diagnostics: IXamlDiagnostics = site.cast()?;
            let mut data = BSTR::default();
            // SAFETY: `data` is a valid out pointer.
            unsafe { diagnostics.GetInitializationData(&raw mut data) }.ok()?;
            let init = InitData::decode(&data.display().to_string())
                .ok_or_else(|| Error::from(E_INVALIDARG))?;
            let service: IVisualTreeService2 = site.cast()?;
            tree::start(service, init);
            Ok(())
        })
    }

    fn GetSite(&self, _iid: *const GUID, _out: *mut *mut c_void) -> Result<()> {
        Err(E_NOTIMPL.into())
    }
}
